class ReportConfig {
  title?: string;
  footer?: string;
  includeSummary = false;
  setTitle(t: string) { this.title = t; return this; }
  setFooter(f: string) { this.footer = f; return this; }
  setIncludeSummary(v: boolean) { this.includeSummary = v; return this; }
}
const cfg = new ReportConfig().setTitle("Q1").setIncludeSummary(true);

class OrderBuilder {
  private items: string[] = [];
  private priority = false;
  addItem(item: string) { this.items.push(item); return this; }
  setPriority(p: boolean) { this.priority = p; return this; }
  build() { return new Order(this.items, this.priority); }
}
const order = new OrderBuilder().addItem('a').setPriority(true).build();

